// (except <body>) that don't match the user's role.
// ---------------------------------------------------------------------------
export function hideElementsWithoutPermission(user) {
  document.querySelectorAll("[data-permission]").forEach(function (el) {
    const req = el.getAttribute("data-permission");
    if (req && !userCan(user, req)) {
      el.style.display = "none";
      el.setAttribute("aria-hidden", "true");
    }
  });
  document.querySelectorAll("[data-role]").forEach(function (el) {
    if (el === document.body) return;
    const reqRole = el.getAttribute("data-role");
    if (
      reqRole &&
      user?.role.name.toLowerCase() !== reqRole.toLowerCase()
    ) {
      el.style.display = "none";
      el.setAttribute("aria-hidden", "true");
    }
  });
}

// ---------------------------------------------------------------------------
// createTestRunner()
// Returns a lightweight test-runner compatible with window.runRbacTests().
// ---------------------------------------------------------------------------
export function createTestRunner() {
  const results = [];
  return {
    test: function (name, fn) {
      const start = performance.now();
      try {
        const result = fn();
        if (result && typeof result.then === "function") {
          return result
            .then(function (): void {
              results.push({
                name: name,
                passed: true,
                message: "Passed",
                duration: performance.now() - start,
              });
            })
            .catch(function (err) {
              results.push({
                name: name,
                passed: false,
                message: err.message || String(err),
                duration: performance.now() - start,
              });
            });
        }
        results.push({
          name: name,
          passed: true,
          message: "Passed",
          duration: performance.now() - start,
        });
        return Promise.resolve();
      } catch (err) {
        results.push({
          name: name,
          passed: false,
          message: err.message || String(err),
          duration: performance.now() - start,
        });
        return Promise.resolve();
      }
    },
    assert: function (cond, msg) {
      if (!cond) throw new Error("Assertion failed: " + msg);
    },
    assertEqual: function (a, b, msg) {
      if (a !== b)
        throw new Error(
          msg ?? "Expected " + JSON.stringify(b) + ", got " + JSON.stringify(a),
        );
    },
    assertVisible: function (sel) {
      const el = document.querySelector(sel);
      if (!el) throw new Error("Element not found: " + sel);
      const s = window.getComputedStyle(el);
      if (
        s.display === "none" ||
        s.visibility === "hidden" ||
        s.opacity === "0"
      )
        throw new Error("Element not visible: " + sel);
    },
    assertHidden: function (sel) {
      const el = document.querySelector(sel);
      if (!el) return; // element absent → treated as hidden
      const s = window.getComputedStyle(el);
      if (
        s.display !== "none" &&
        s.visibility !== "hidden" &&
        s.opacity !== "0"
      )
        throw new Error("Element should be hidden: " + sel);
    },
    getResults: function (): void {
      return results;
    },
    getSummary: function (): void {
      return {
        total: results.length,
        passed: results.filter(function (r) {
          return r.passed;
        }).length,
        failed: results.filter(function (r) {
          return !r.passed;
        }).length,
        duration: results.reduce(function (s, r) {
          return s + r.duration;
        }, 0),
      };
    },
  };
}

